  const query = await searchParams;
  const tab = query.tab ?? "posts";
  const offset = validateOffset(query.offset);
  const href = `/u/${username}`;
  if (
    offset === null ||
    (tab !== "posts" && tab !== "followers" && tab !== "following")
  )
    return <ServiceError message="목록 주소를 확인해 주세요." href={href} />;
  const [result, viewer] = await Promise.all([
    readProfile(username),
    getViewer(),
  ]);
  if (!result.ok)
    return <ServiceError message="프로필을 불러오지 못했습니다." href={href} />;
  if (!result.profile) notFound();
  const profile = result.profile;
  const relationship =
    viewer.status === "ready" && viewer.id !== profile.id
      ? await readFollowing(viewer.id, profile.id)
      : null;
  const posts = tab === "posts" ? await readPosts(offset, profile.id) : null;
  const connections =
    tab !== "posts" ? await readConnections(profile.id, tab, offset) : null;
  const hasMore =
    (posts?.ok && posts.hasMore) || (connections?.ok && connections.hasMore);
  return (
    <>
      <header className="page-heading">
        <h1>프로필</h1>
      </header>
      <section className="profile-header stack" aria-label="사용자 소개">
        <div className="profile-identity">
          <Avatar name={profile.display_name} />
          <div className="person-copy">
            <h2>{profile.display_name}</h2>
            <p className="post-meta">@{profile.username}</p>
          </div>
        </div>
        {profile.bio && <p className="post-body muted">{profile.bio}</p>}
        {viewer.status === "ready" &&
          relationship &&
          (relationship.ok ? (
            <SessionBoundary
              key={viewer.id}
              userId={viewer.id}
              generation={crypto.randomUUID()}
            >
              <FollowButton
                key={profile.id}
                userId={viewer.id}
                targetId={profile.id}
                following={relationship.following}
              />
            </SessionBoundary>
          ) : (
            <ServiceError
              message="팔로우 상태를 확인하지 못했습니다."
              href={href}
            />
          ))}
        {viewer.status === "guest" && (
          <Link className="text-link" href="/login">
            로그인하고 팔로우하기
          </Link>
        )}
        {viewer.status === "onboarding" && (
          <Link className="text-link" href="/onboarding">
            프로필 설정 후 팔로우하기
          </Link>
        )}
        {viewer.status === "error" && (
          <p className="error">
            로그인 상태를 확인하지 못했습니다. 새로고침해 주세요.
          </p>
        )}
      </section>
      <nav className="profile-tabs" aria-label="프로필 목록">
        <Link href={href} aria-current={tab === "posts" ? "page" : undefined}>
          글
        </Link>
        <Link
          href={`${href}?tab=followers`}
          aria-current={tab === "followers" ? "page" : undefined}
        >
          팔로워 {profile.followers[0]?.count ?? 0}
        </Link>
        <Link
          href={`${href}?tab=following`}
          aria-current={tab === "following" ? "page" : undefined}
        >
          팔로잉 {profile.following[0]?.count ?? 0}
        </Link>
      </nav>
      {posts &&
        (!posts.ok ? (
          <ServiceError message="글을 불러오지 못했습니다." href={href} />
        ) : posts.posts.length ? (
          posts.posts.map((post) => <PostRow key={post.id} post={post} />)
        ) : (
          <p className="empty muted">
            {offset > 0
              ? "이 페이지에 표시할 글이 없습니다. 처음 목록을 확인해 주세요."
              : "아직 작성한 글이 없습니다."}
          </p>
        ))}
      {connections &&
        (!connections.ok ? (
          <ServiceError
            message={`${tab === "followers" ? "팔로워" : "팔로잉"} 목록을 불러오지 못했습니다.`}
            href={`${href}?tab=${tab}`}
          />
        ) : connections.people.length ? (
          <ul className="person-list">
            {connections.people.map((person) => (
              <PersonRow key={person.id} person={person} />
            ))}
          </ul>
        ) : (
          <p className="empty muted">
            {offset > 0
              ? `이 페이지에 표시할 ${tab === "followers" ? "팔로워가" : "팔로잉한 사람이"} 없습니다. 처음 목록을 확인해 주세요.`
              : `아직 ${tab === "followers" ? "팔로워가" : "팔로잉한 사람이"} 없습니다.`}
          </p>
        ))}
      <div className="feed-footer actions">
        {offset > 0 && (
          <Link className="text-link" href={`${href}?tab=${tab}`}>
            처음으로
          </Link>
        )}
        {hasMore && (
          <Link
            className="button button-outline"
            href={`${href}?tab=${tab}&offset=${offset + PAGE_SIZE}`}
          >
            더 보기
          </Link>
        )}
      </div>
    </>
  );
}
"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import {
  readFields,
  validateCredentials,
  validateProfile,
} from "@/lib/validation";
import {
  databaseFailure,
  uncertainWrite,
  type ActionResult,
} from "@/lib/action-result";

function authFailure(error: { code?: string; status?: number }): ActionResult {
  if (error.status === 429)
    return {
      status: "error",
      message: "요청이 많습니다. 잠시 기다린 뒤 다시 시도해 주세요.",
    };
  if (error.code === "invalid_credentials")
    return {
      status: "input",
      message: "이메일 또는 비밀번호를 확인해 주세요.",
    };
  if (error.code === "user_already_exists" || error.code === "email_exists")
    return {
      status: "input",
      message: "이미 가입된 이메일입니다. 로그인해 주세요.",
    };
  if (error.code === "email_not_confirmed")
    return {
      status: "error",
      message:
        "이메일 확인이 필요한 계정입니다. 현재 서비스의 가입 설정을 운영자가 확인해야 합니다.",
    };
  if (error.code === "weak_password")
    return {
      status: "input",
      message:
        "더 긴 비밀번호를 사용해 주세요. 현재 서비스의 비밀번호 조건을 충족해야 합니다.",
    };
  if (error.code === "signup_disabled")
    return {
      status: "error",
      message: "현재 신규 가입을 받을 수 없습니다. 잠시 후 다시 시도해 주세요.",
    };
  return {
    status: "uncertain",
    message:
      "인증 결과를 확인하지 못했습니다. 잠시 후 로그인 화면에서 다시 확인해 주세요.",
  };
}

async function authenticate(
  form: FormData,
  signup: boolean,
): Promise<ActionResult> {
  const fields = readFields(form, ["email", "password"]);
  if (!fields.ok) return { status: "input", message: fields.message };
  const values = validateCredentials(fields.value, signup);
  if (!values.ok) return { status: "input", message: values.message };
  try {
    const client = await createClient();
    const { data, error } = signup
      ? await client.auth.signUp(values.value)
      : await client.auth.signInWithPassword(values.value);
    if (error) return authFailure(error);
    if (!data.session || !data.user || data.user.is_anonymous)
      return {
        status: "error",
        message:
          "가입 후 로그인 세션을 확인하지 못했습니다. 계정을 다시 만들지 말고 로그인해 주세요. 계속되면 운영자의 가입 설정 확인이 필요합니다.",
      };
    revalidatePath("/", "layout");
    return {
      status: "success",
      message: signup
        ? "가입했습니다. 공개 프로필을 설정해 주세요."
        : "로그인했습니다.",
    };
  } catch {
    return authFailure({});
  }
}

export async function signUp(form: FormData) {
  return authenticate(form, true);
}
export async function signIn(form: FormData) {
  return authenticate(form, false);
}

export async function signOut(): Promise<ActionResult> {
  try {
    const client = await createClient();
    const { error } = await client.auth.signOut({ scope: "local" });
    if (error)
      return {
        status: "error",
        message: "로그아웃을 완료하지 못했습니다. 다시 시도해 주세요.",
      };
    revalidatePath("/", "layout");
    return { status: "success", message: "로그아웃했습니다." };
  } catch {
    return {
      status: "uncertain",
      message: "로그아웃 결과를 확인하지 못했습니다. 새로고침해 확인해 주세요.",
    };
  }
}

export async function completeProfile(
  expectedUserId: string,
  form: FormData,
): Promise<ActionResult> {
  try {
    const client = await createClient();
    const { data, error } = await client.auth.getUser();
    if (error || !data.user || data.user.is_anonymous)
      return {
        status: "error",
        message: "로그인 상태를 확인하지 못했습니다. 다시 로그인해 주세요.",
      };
    if (data.user.id !== expectedUserId)
      return {
        status: "error",
        message: "로그인 계정이 변경됐습니다. 페이지를 새로고침해 주세요.",
      };
    const fields = readFields(form, ["username", "display_name", "bio"]);
    if (!fields.ok) return { status: "input", message: fields.message };
    const values = validateProfile(fields.value);
    if (!values.ok) return { status: "input", message: values.message };
    const { data: existing, error: readError } = await client
      .from("profiles")
      .select("id")
      .eq("id", data.user.id)
      .maybeSingle();
    if (readError) return databaseFailure(readError.code);
    if (existing)
      return {
        status: "success",
        message: "공개 프로필이 이미 설정되어 있습니다.",
      };
    const { data: saved, error: insertError } = await client
      .from("profiles")
      .insert(values.value)
      .select("id")
      .single();
    if (insertError) return databaseFailure(insertError.code);
    if (!saved || saved.id !== data.user.id) return uncertainWrite;
    revalidatePath("/", "layout");
    return { status: "success", message: "공개 프로필을 저장했습니다." };
  } catch {
    return uncertainWrite;
  }
}
# SNS 구현 명세

기준 문서: `docs/assignment.md`에 보존한 8around 원본 README. 원문과 충돌하면 원문을 우선한다. 이 문서의 세부 정책은 구현 결정이다. 아래 파일·명령·기능은 구현 대상이며, 실제 실행 전에는 완료로 기록하지 않는다.

## 1. 완성할 결과

외부 방문자가 가입하고 로그인하여 글을 작성한다. 별도 계정이 같은 글을 읽고 댓글을 달며, 작성자가 답글을 단다. 다른 사용자를 팔로우하고 양쪽 관계 목록을 확인한다. 동일한 소스로 로컬 앱 실행, 공개 배포, 반복 가능한 검사를 제공한다.

| 기능 | 구현 계약 |
|---|---|
| 가입·로그인 | Supabase Auth 이메일·비밀번호 인증. 신규 가입, 로그인, 로그아웃, 새로고침·페이지 이동 후 유효 세션 유지. |
| 프로필 | 가입 후 사용자명·표시 이름·소개를 입력한다. 미완료 계정은 프로필 단계로 복귀한다. 계정을 다시 생성하지 않는다. |
| 게시글 | 텍스트 작성, 전체 최신순 피드, 글 상세, 작성자 프로필 연결. |
| 댓글·답글 | 게시글의 최상위 댓글과 그 댓글에 대한 한 단계 답글. 부모·자식 관계를 저장하고 표시한다. |
| 팔로우 | 단방향 팔로우·해제, 팔로워 목록·팔로잉 목록과 각각의 수. 목록과 수는 같은 관계 데이터를 읽는다. |
| UI | 반응형 화면, 빈 상태, 입력 오류, 처리 중, 성공, 통신 오류. 실제로 없는 기능의 버튼은 표시하지 않는다. |
| 제출 | Public GitHub, 공개 배포 URL, README, tool.md, 실제 AI 기록 exports/, 소스와 검증 기록. |

### 제품 정책

- 공개 피드·프로필·댓글은 누구나 읽는다. 쓰기와 팔로우에는 로그인 및 프로필 완료가 필요하다.
- 이메일 확인 메일은 사용하지 않는다. 익명 계정 기능은 사용하지 않는다. 실제 비밀번호 인증은 유지한다. 이메일 소유권 확인과 메일 기반 계정 복구는 제공하지 않으며 가입 화면·README에 이를 밝힌다.
- 사용자명은 소문자 영문·숫자·밑줄 3~20자, 고유값이다. 표시 이름은 1~30 코드 포인트, 소개는 160 이내다. 초기 프로필 설정 이후 편집은 제공하지 않는다.
- 글·댓글은 앞뒤 공백을 정리한 일반 텍스트, 1~500 Unicode 코드 포인트다. 줄바꿈을 보존한다. 화면·서버에서 동일한 검증 함수를 사용하고 SQL에서도 공백 본문과 한도 초과를 막는다.
- 피드는 `created_at DESC, id DESC`, 20개씩 ‘더 보기’로 읽는다. offset 페이지 방식을 사용하며 새 작성·새로고침 시 첫 페이지부터 읽는다. 읽는 중 삽입에 대한 완전한 시점 일관성은 보장하지 않는다.
- 사람·팔로워·팔로잉 목록도 페이지를 나누고 더 보기를 제공한다. 댓글은 최상위 댓글을 나누어 읽고, 해당 부모 아래의 답글을 별도로 펼쳐 읽는다. 답글만 부모 없이 표시하지 않는다.
- 최상위 댓글의 깊이는 0, 답글은 1이다. 답글의 자식 생성은 거절한다. 댓글 수는 답글을 포함한다. 원문은 최대 깊이를 지정하지 않았으므로 이 제한은 선택한 정책으로 문서화한다.
- 프로필·글·댓글 삭제/수정, 파일 업로드, 좋아요, DM, 알림, 추천, 실시간 전송, 다크모드, 소셜 로그인은 구현하지 않는다.

## 2. 실행 구성

| 대상 | 구성 |
|---|---|
| 개발 | GitHub Codespaces 한 대. Codex CLI, 앱 개발 서버, 패키지 설치, 필요한 검사 실행. |
| 데이터 | 과제 전용 Supabase Cloud 프로젝트 한 개. Auth와 PostgreSQL 사용. 다른 서비스의 DB를 재사용하지 않는다. |
| 공개 | Netlify 사이트 한 개, Next.js 지원 어댑터 기본 구성. 배포된 앱이 Codespaces를 호출하지 않는다. |
| 자동 검사 | GitHub Actions 워크플로 하나. Docker 없이 정적 검사·단위 검사·빌드만 실행한다. |
| 로컬 경로 | Node·Git·npm으로 Next.js만 실행하고 원격 Supabase에 연결한다. README에 이를 명시한다. |

Next.js App Router + TypeScript + Tailwind CSS + shadcn/ui의 Radix 기반 부품 + Lucide를 사용한다. 런타임은 Node 24 LTS, 패키지 관리자는 npm이다. 이미 호환되는 앱이 있다면 보존한다. 새 앱은 지원 중인 안정 버전으로 초기화하고 실제 버전과 `package-lock.json`을 기록한다. 프레임워크 교체·실험 기능 도입은 하지 않는다.

앱은 하나의 저장소에 둔다. `main` 한 브랜치를 기준으로 작은 변경을 기록한다. 별도 release 브랜치·다중 배포 파이프라인·ORM·전역 상태 라이브러리·캐시 서버·범용 repository 계층은 만들지 않는다.

개발 앱과 제출 앱은 같은 과제 전용 DB를 사용한다. 이것은 환경 격리를 제공하지 않는 선택이다. 따라서 자동 초기화·삭제 테스트·부하 테스트를 금지한다. 신규 구조 변경은 파일로 검토하고 추가형으로 적용한다. 실제 사용자 데이터가 생긴 뒤 파괴적 변경은 중단한다. 이미 별도 환경이 구성되어 있다면 삭제하거나 합치지 않고 현재 연결을 먼저 확인한다.

Free 플랜과 기존 허용 사용량 안에서만 작업한다. 비용·유료 전환·한도 우회는 승인하지 않는다. 작업 후 Codespace를 중지한다. 무료 호스팅의 한도·일시정지를 무중단 보장으로 표현하지 않는다.

### 설정

앱의 `.env.example`에는 아래 이름과 비밀 없는 예시만 둔다.

```dotenv
NEXT_PUBLIC_SUPABASE_URL=https://YOUR_PROJECT.supabase.co
NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=YOUR_PUBLISHABLE_KEY
```

실제 값은 Codespaces의 `.env.local`과 Netlify 환경 설정에 넣는다. URL·publishable key는 공개 클라이언트용 정보이며 권한 보호는 RLS가 담당한다. DB 비밀번호·service_role·secret key는 앱과 일반 Codex 작업 환경에 넣지 않는다.

Supabase 설정은 신규 가입 허용, 이메일·비밀번호 사용, Confirm Email 비활성, 익명 로그인 비활성이다. 기본 Auth 요청 제한을 완화하지 않고 실제 가입·로그인에서 제한 오류를 처리한다. 추가 CAPTCHA·메일·도메인 서비스는 기본 의존성으로 넣지 않는다. 공개 운영의 남용 방어·계정 복구 한계는 README에 남긴다.

## 3. 화면과 요청 처리

| 경로 | 화면의 역할 |
|---|---|
| `/` | 글 작성 영역과 최신 피드. 비로그인 시 읽기와 가입·로그인 안내. |
| `/signup`, `/login` | 신규 가입, 로그인, 오류 안내. 비밀번호를 로그에 남기지 않는다. |
| `/onboarding` | 공개 프로필 최초 설정. 사용자명 충돌 시 이 단계만 재시도. |
| `/posts/[id]` | 본문, 최상위 댓글 입력, 댓글·답글 보기, 답글 대상·취소. |
| `/people` | 프로필을 찾고 방문하는 작은 사용자 목록. |
| `/u/[username]` | 소개, 해당 사용자의 글, 팔로우 버튼. `tab=followers`와 `tab=following`으로 두 목록 제공. |

조회는 Server Component에서 필요한 공개 필드만 가져온다. 쓰기는 기능별 Server Action으로 모은다. 폼·상태 전환만 Client Component로 만든다. 동일한 기능에 REST API를 중복 작성하지 않는다.

인증은 `@supabase/ssr`의 공식 Next.js 구성을 따른다. 요청별 서버 클라이언트와 쿠키 갱신을 구성한다. 보호된 쓰기에서 `getUser()`로 사용자를 확인하며, `getSession()`의 사용자 객체만 신뢰하지 않는다. 설치한 버전에 맞는 proxy/middleware 파일명을 사용한다.

쓰기 순서: 사용자 확인 → 입력 검사 → 필요한 대상 조회 → RLS가 적용된 저장 → 영향받은 경로 재조회 → 실제 결과 표시. 클라이언트에서 보낸 작성자·작성 시각·권한 항목은 허용하지 않는다. Server Action의 출처 보호를 비활성화하지 않는다.

세션과 개인별 UI 상태를 공용 캐시에 넣지 않는다. DB 조회 페이지는 빌드 시 DB에 접속하지 않도록 동적 처리한다. 빌드 통과를 위해 런타임의 설정 누락을 빈 목록이나 가짜 데이터로 숨기지 않는다.

## 4. DB 구조와 접근 규칙

`supabase/migrations/`에 초기 SQL을 작성한다. 소유자가 확인한 신규 과제 프로젝트의 SQL Editor에서 같은 파일을 한 번 적용하는 것을 기본 경로로 한다. 재현 가능한 실제 적용 순서와 후속 변경을 README에 적는다. 실행하지 않은 SQL을 적용 완료로 기록하지 않는다.

| 테이블 | 주요 열·관계 |
|---|---|
| `profiles` | `id uuid PRIMARY KEY` → `auth.users.id`; `username UNIQUE`; `display_name`; `bio`; `created_at`. |
| `posts` | `id uuid PRIMARY KEY`; `author_id` → `profiles.id`; `content`; `created_at`. |
| `comments` | `id uuid PRIMARY KEY`; `post_id` → `posts.id`; `parent_id` nullable; `author_id` → `profiles.id`; `content`; `created_at`. |
| `follows` | `follower_id`·`followee_id` → `profiles.id`; 두 열의 복합 기본키; `created_at`; 자기 관계 금지. |

