import { Avatar } from "@/components/avatar";
import Link from "next/link";
import {
  readRoots,
  readRoot,
  readReplies,
  type ThreadComment,
} from "@/lib/comments";
import { commentPageHref, parseCommentPage } from "@/lib/comment-page";
import { PAGE_SIZE } from "@/lib/validation";
import type { Viewer } from "@/lib/viewer";
import { CommentComposer } from "@/components/comment-composer";
import { SessionBoundary } from "@/components/session-boundary";
import { ServiceError } from "@/components/service-error";

function CommentBody({ comment }: { comment: ThreadComment }) {
  return (
    <div className="comment-content">
      <Avatar name={comment.author?.display_name} />
      <div className="post-copy">
        <header className="post-header">
          {comment.author ? (
            <Link
              className="post-author"
              href={`/u/${comment.author.username}`}
            >
              {comment.author.display_name}
            </Link>
          ) : (
            <span className="post-author">알 수 없는 작성자</span>
          )}
          <span className="post-meta">
            @{comment.author?.username ?? "unknown"}
          </span>
          <time className="post-meta" dateTime={comment.created_at}>
            {new Intl.DateTimeFormat("ko-KR", {
              timeZone: "Asia/Seoul",
              month: "long",
              day: "numeric",
              hour: "2-digit",
              minute: "2-digit",
            }).format(new Date(comment.created_at))}
          </time>
        </header>
        <p className="post-body">{comment.content}</p>
      </div>
    </div>
  );
}

export async function CommentsSection({
  postId,
  count,
  viewer,
  page,
}: {
  postId: string;
  count: number;
  viewer: Viewer;
  page: NonNullable<ReturnType<typeof parseCommentPage>>;
}) {
  const { offset, thread, replyOffset } = page;
  const href = commentPageHref(postId, offset);
  const roots = await readRoots(postId, offset);
  let selected = roots.ok
    ? roots.comments.find((comment) => comment.id === thread)
    : undefined;
  let selectionError = "";
  if (thread && !selected) {
    const result = await readRoot(postId, thread);
    if (!result.ok) selectionError = "답글 대상을 불러오지 못했습니다.";
    else if (!result.comment)
      selectionError = "이 글에 직접 남긴 댓글을 답글 대상으로 선택해 주세요.";
    else selected = result.comment;
  }
  const replies = selected ? await readReplies(selected, replyOffset) : null;
  // A linked older root stays visible even when it is outside the current root page.
  const comments = roots.ok
    ? [
        ...(selected && !roots.comments.some((root) => root.id === selected.id)
          ? [selected]
          : []),
        ...roots.comments,
      ]
    : selected
      ? [selected]
      : [];
  const content = (
    <section
      id="comments"
      className="comments-section"
      aria-label="댓글과 답글"
    >
      <div className="page-heading">
        <h2>댓글 {count}개</h2>
        <span className="hint">답글 포함 · 최신순</span>
      </div>
      {viewer.status === "ready" ? (
        <CommentComposer userId={viewer.id} postId={postId} />
      ) : viewer.status === "error" ? (
        <p className="notice error">
          로그인 상태를 확인하지 못했습니다. 새로고침해 주세요.
        </p>
      ) : (
        <p className="notice">
          <Link
            className="text-link"
            href={viewer.status === "onboarding" ? "/onboarding" : "/login"}
          >
            {viewer.status === "onboarding"
              ? "프로필 설정 후 댓글 남기기"
              : "로그인하고 댓글 남기기"}
          </Link>
        </p>
      )}
      {selectionError && (
        <ServiceError message={selectionError} href={`${href}#comments`} />
      )}
      {!roots.ok && (
        <ServiceError
          message="댓글을 불러오지 못했습니다."
          href={`${href}#comments`}
        />
      )}
      {roots.ok && comments.length === 0 && (
        <p className="empty muted">
          {offset
            ? "이 페이지에는 댓글이 없습니다."
            : "첫 번째 댓글을 남겨 주세요."}
        </p>
      )}
      {comments.map((comment) => (
        <article
          className="comment-root"
          id={`comment-${comment.id}`}
          key={comment.id}
        >
          <CommentBody comment={comment} />
          <div className="comment-actions">
            {viewer.status === "ready" && (
              <CommentComposer
                userId={viewer.id}
                postId={postId}
                offset={offset}
                parent={{
                  id: comment.id,
                  displayName: comment.author?.display_name ?? "작성자",
                }}
              />
            )}
            {comment.id === selected?.id ? (
              <Link
                className="text-link"
                href={`${href}#comment-${comment.id}`}
                scroll={false}
              >
                답글 접기
              </Link>
            ) : (
              <Link
                className="text-link"
                href={`${commentPageHref(postId, offset, comment.id)}#comment-${comment.id}`}
                scroll={false}
              >
                답글 보기
              </Link>
            )}
          </div>
          {comment.id === selected?.id && replies && (
            <div
              className="replies"
              aria-label={`${comment.author?.display_name ?? "작성자"}님의 댓글에 달린 답글`}
            >
              {!replies.ok ? (
                <ServiceError
                  message="답글을 불러오지 못했습니다."
                  href={commentPageHref(
                    postId,
                    offset,
                    comment.id,
                    replyOffset,
                  )}
                />
              ) : (
                <>
                  {replies.comments.map((reply) => (
                    <article
                      className="comment-reply"
                      id={`comment-${reply.id}`}
                      key={reply.id}
                    >
                      <CommentBody comment={reply} />
                    </article>
                  ))}
                  {replies.comments.length === 0 && (
                    <p className="notice muted">
                      아직 이 페이지에 답글이 없습니다.
                    </p>
                  )}
                  <div className="actions">
                    {replyOffset > 0 && (
                      <Link
                        className="text-link"
                        href={`${commentPageHref(postId, offset, comment.id)}#comment-${comment.id}`}
                        scroll={false}
                      >
                        첫 답글 페이지
                      </Link>
                    )}
                    {replies.hasMore && (
                      <Link
                        className="button button-outline"
                        href={`${commentPageHref(postId, offset, comment.id, replyOffset + PAGE_SIZE)}#comment-${comment.id}`}
                        scroll={false}
                      >
                        답글 더 보기
                      </Link>
                    )}
                  </div>
                </>
              )}
            </div>
          )}
        </article>
      ))}
      <div className="feed-footer actions">
        {offset > 0 && (
          <Link
            className="text-link"
            href={`${commentPageHref(postId)}#comments`}
          >
            첫 댓글 페이지
          </Link>
        )}
        {roots.ok && roots.hasMore && (
          <Link
            className="button button-outline"
            href={`${commentPageHref(postId, offset + PAGE_SIZE)}#comments`}
          >
            댓글 더 보기
          </Link>
        )}
      </div>
    </section>
  );
  return viewer.status === "ready" ? (
    <SessionBoundary
      key={`${viewer.id}:${postId}`}
      userId={viewer.id}
      generation={crypto.randomUUID()}
    >
      {content}
    </SessionBoundary>
  ) : (
    content
  );
}
"use client";

import Link from "next/link";
import { useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { createComment } from "@/actions/comments";
import {
  codePointLength,
  normalizeText,
  validateComment,
} from "@/lib/validation";
import { commentPageHref } from "@/lib/comment-page";
import { uncertainWrite, type ActionResult } from "@/lib/action-result";
import { Button } from "@/components/ui/button";
import { actionMessage } from "@/components/action-message";

export function CommentComposer({
  userId,
  postId,
  offset = 0,
  parent,
}: {
  userId: string;
  postId: string;
  offset?: number;
  parent?: { id: string; displayName: string };
}) {
  const router = useRouter();
  const [open, setOpen] = useState(!parent);
  const [content, setContent] = useState("");
  const [pending, setPending] = useState(false);
  const busy = useRef(false);
  const restoreFocus = useRef(false);
  const [result, setResult] = useState<ActionResult | null>(null);
  const inputId = `comment-input-${parent?.id ?? "root"}`;
  const destination = commentPageHref(postId, parent ? offset : 0, parent?.id);
  if (!open)
    return (
      <Button
        variant="ghost"
        ref={(button) => {
          if (button && restoreFocus.current) {
            restoreFocus.current = false;
            button.focus();
          }
        }}
        onClick={() => setOpen(true)}
      >
        답글 쓰기
      </Button>
    );
  return (
    <form
      className="comment-composer stack"
      onSubmit={async (event) => {
        event.preventDefault();
        if (busy.current) return;
        const checked = validateComment({
          post_id: postId,
          parent_id: parent?.id ?? "",
          content,
        });
        if (!checked.ok) {
          setResult({ status: "input", message: checked.message });
          return;
        }
        const form = new FormData(event.currentTarget);
        busy.current = true;
        setPending(true);
        setResult(null);
        try {
          const next = await createComment(userId, form);
          setResult(next);
          if (next.status === "success") {
            setContent("");
            router.replace(`${destination}#comment-${next.id}`);
            router.refresh();
          }
        } catch {
          setResult(uncertainWrite);
        } finally {
          busy.current = false;
          setPending(false);
        }
      }}
    >
      <input type="hidden" name="post_id" value={postId} />
      <input type="hidden" name="parent_id" value={parent?.id ?? ""} />
      <div className="field">
        <label htmlFor={inputId}>
          {parent ? `${parent.displayName}님에게 답글` : "댓글 남기기"}
        </label>
        <textarea
          id={inputId}
          name="content"
          className="input"
          autoFocus={Boolean(parent)}
          placeholder={
            parent
              ? "이 이야기에 답해 주세요."
              : "함께 나누고 싶은 이야기가 있나요?"
          }
          value={content}
          disabled={pending}
          onChange={(event) => setContent(event.target.value)}
          aria-describedby={`${inputId}-count ${inputId}-feedback`}
          aria-invalid={result?.status === "input"}
        />
      </div>
      <div className="form-footer">
        <span className="hint" id={`${inputId}-count`}>
          {codePointLength(normalizeText(content))} / 500자
        </span>
        <div className="actions">
          {parent && (
            <Button
              type="button"
              variant="ghost"
              disabled={pending}
              onClick={() => {
                restoreFocus.current = true;
                setOpen(false);
              }}
            >
              취소
            </Button>
          )}
          <Button className="comment-submit" type="submit" disabled={pending}>
            {pending ? "남기는 중…" : parent ? "답글 남기기" : "댓글 남기기"}
          </Button>
        </div>
      </div>
      <div id={`${inputId}-feedback`} aria-live="polite">
        {result && (
          <p className={result.status === "success" ? "success" : "error"}>
            {result.status === "uncertain"
              ? "저장 결과를 확인하지 못했습니다. 입력한 내용은 남아 있습니다."
              : actionMessage(result.message)}
            {result.status === "success" && result.id && (
              <>
                {" "}
                <Link
                  href={`${destination}#comment-${result.id}`}
                  className="text-link"
                >
                  남긴 {parent ? "답글" : "댓글"} 보기
                </Link>
              </>
            )}
          </p>
        )}
      </div>
      {result?.status === "uncertain" && (
        <Button
          type="button"
          variant="outline"
          onClick={() => router.refresh()}
        >
          초안을 유지하고 댓글 확인
        </Button>
      )}
    </form>
  );
}
