        /\b(?:sb_secret_|sb_publishable_|sk-proj-|sk-|gh[pousr]_|github_pat_)[A-Za-z0-9_-]{16,}\b/g,
      ])
        value = replace(value, pattern, "[REDACTED_TOKEN]");
      value = replace(
        value,
        /data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=\r\n]+/gi,
        "[REDACTED_LOCAL_IMAGE_ATTACHMENT]",
      );
      return value;
    }
    if (Array.isArray(value))
      return value.map((item) => sanitize(item, objectDepth + 1, jsonDepth));
    if (value && typeof value === "object") {
      if (value.type === "input_image") {
        if (value.image_url !== "[REDACTED_LOCAL_IMAGE_ATTACHMENT]")
          stats.redactions++;
        return {
          type: "input_image",
          image_url: "[REDACTED_LOCAL_IMAGE_ATTACHMENT]",
        };
      }
      return Object.fromEntries(
        Object.entries(value).map(([key, item]) => [
          sanitize(key, objectDepth + 1, jsonDepth),
          /^(?:encryptionKey|encryption\.key)$/.test(key) &&
          typeof item === "string" &&
          /^[A-Za-z0-9+/=]{20,}$/.test(item)
            ? (stats.redactions++, "[REDACTED_BUILD_KEY]")
            : sanitize(item, objectDepth + 1, jsonDepth),
        ]),
      );
    }
    return value;
  }
  return { sanitize, stats };
}
# 사용한 도구

## AI 작업과 디자인

| 도구                                 | 실제 사용한 일                                                                                                                                      |
| ------------------------------------ | --------------------------------------------------------------------------------------------------------------------------------------------------- |
| ChatGPT                              | 과제 해석, 구현·교정 작업서와 README 초안 작성, 공개 저장소·CI 대조 검토에 사용했습니다. 앱을 직접 수정하거나 공개 배포한 것으로 기록하지 않습니다. |
| OpenAI Codex CLI 0.154.0             | 요구사항과 코드를 읽고, 기능 구현·오류 수정·검사 실행을 진행했습니다.                                                                               |
| Codex의 셸·파일 수정·웹 조회 도구    | 파일 변경, 패키지 설치, 빌드와 검사를 실행하고 관련 공식 문서를 확인했습니다.                                                                       |
| OpenAI Docs 스킬                     | Codex 실행 기록과 내보내기 방법을 확인하는 데 사용했습니다.                                                                                         |
| Oh My Design CLI 2.0.0의 `omd:apply` | `DESIGN.md`를 기준으로 기존 화면을 수정했습니다.                                                                                                    |
| 같은 배포물의 `omd:feel`             | 입력 경계, 색 대비, 조작 영역, 포커스와 움직임 감소를 점검했습니다.                                                                                 |
| 같은 배포물의 `omd:slop-audit`       | 반복된 홍보 문구와 장식을 줄이고, 같은 화면의 수정 전후를 비교했습니다.                                                                             |
| Playwright 1.63.0와 Chromium         | 개발용 검사 환경에서 로그인, 게시, 답글, 팔로우, 모바일 화면과 실패 상황을 확인했습니다. 앱 실행 의존성에는 넣지 않았습니다.                        |

Oh My Design의 세 `SKILL.md`는 Codex에서 읽을 수 있는 위치에 등록되어 있습니다. 별도의 스킬 호출 API가 없어 문서의 지침을 직접 적용했습니다. 하위 전문가 에이전트나 전체 자동화 파이프라인을 실행한 것으로 기록하지 않습니다. 실제 사용한 CLI는 2.0.0이며, 계획에 한때 적혔던 2.0.1로 바꾸어 쓰지 않습니다.

디자인 참고는 OMD의 Karrot 항목과 SEED 제품 지침입니다. 작성자와 콘텐츠의 읽는 순서, 행동에 대한 피드백을 참고했습니다. 당근의 브랜드 자산이나 거래 화면을 복제하지 않았고, SEED 패키지를 앱에 설치하지 않았습니다. 채택한 색·간격·화면 규칙은 [DESIGN.md](DESIGN.md)에 있습니다.

앱 구현에 추가 MCP, 병렬 에이전트, 이미지 생성 도구, 유료 디자인 API는 사용하지 않았습니다. 완성된 SNS가 글을 처리할 때 AI 모델을 호출하지도 않습니다.

## 앱과 검사 라이브러리

화면과 서버에는 Next.js·React·TypeScript, 인증과 저장에는 Supabase Auth·PostgreSQL을 사용했습니다. UI에는 Tailwind CSS, shadcn/ui에서 가져온 Radix 기반 Button, Lucide, Pretendard를 사용했습니다. 형식과 코드 검사는 Prettier·ESLint·TypeScript·Vitest로 구성했습니다.

정확한 의존성 버전은 [package.json](package.json)과 [package-lock.json](package-lock.json), 출처와 라이선스는 [THIRD_PARTY_NOTICES.md](THIRD_PARTY_NOTICES.md)에 보존합니다. `AGENTS.md`는 작업 규칙, `IMPLEMENTATION_PLAN.md`는 기능 계약, `DESIGN.md`는 화면의 기준으로 사용했습니다.

## 실제 대화 기록

[exports/README.md](exports/README.md)에 세션별 파일과 범위를 정리합니다. 공개 파일은 실제 Codex 세션에 남은 입력·응답·도구 결과에서 만들었으며, 나중에 작성한 요약으로 대화를 대신하지 않았습니다.

`scripts/export-session.mjs`는 세션 식별자와 원본 해시로 파일명을 만들어 서로 다른 세션과 스냅샷을 보존합니다. 비공개 원본은 Git에서 제외한 `.ai-raw/`에 남깁니다. 공개 전에는 설정값과 토큰, 개인정보를 점검하고, 검사할 수 없는 이미지 첨부는 제외 표시로 바꿉니다. 임의의 모든 인코딩에서 민감한 값을 자동 검출한다고 보장하지는 않습니다.

현재 기록 형식은 `filtered-codex-rollout`입니다. 확인한 CLI에는 전용 transcript export 명령이 없어 기존 실제 세션을 변환했습니다. 공식 내보내기와 같은 형식이라고 주장하지 않으며, 과제의 export 방식으로 수용되는지는 별도로 확인해야 합니다. 형식 확인 결과와 실제 검사 범위는 [검증 기록](docs/verification.md)에 남깁니다.

설계·감사에 사용한 ChatGPT 대화의 실제 내보내기 파일은 아직 확보하지 못했습니다. 작업서를 그 대화의 원본으로 대신하지 않습니다.
